mapper.select:
SELECT a.CASH_ID AS cashId, /**现金流代码**/ a.CASH_NUM AS cashNum,/**现金流序号**/ a.VDATE_UNADJUST AS vdateUnadjust,/**未调整的计算开始日**/ a.MDATE_UNADJUST AS mdateUnadjust,/**未调整的计算结束日**/ a.PAY_DATE_UNADJUST AS payDateUnadjust,/**未调整的计划支付日**/ a.VDATE AS vdate,/**调整后的计算开始日**/ a.MDATE AS mdate,/**调整后的计算结束日**/ a.PAY_DATE AS payDate,/**调整后的计划支付日**/ a.TERMDAYS AS termdays,/**计算周期天数**/ a.VDATE_Y AS vdateY,/**理论计息年度开始日**/ a.VDATE_TERM AS vdateTerm,/**完整周期开始日**/ a.MDATE_TERM AS mdateTerm,/**完整周期结束日**/ a.TERMDAYS_TERM termdaysTerm,/**完整周期计息天数**/ a.PRIN_AMT AS prinAmt,/**计划支付本金**/ a.IS_PAY_INT AS isPayInt,/**是否支付利息**/ a.INT_AMT AS intAmt,/**计划支付利息**/ a.CASH_AMT AS cashAmt,/**计划支付现金流**/ a.CASH_UNIT_TYPE AS cashUnitType,/**现金流单位**/ a.CALC_FUNCTION AS calcFunction,/**计息算法**/ a.FREQUENCY AS frequency,/**年付息次数**/ a.FINPROD_ID AS finprodId,/**金融产品代码**/ a.FINPROD_TYPE AS finprodType,/**金融产品类型**/ a.PAY_TYPE AS payType, /**支付方式**/ b.BRANCH AS branch,/**分支序号**/ b.CASH_TYPE_1 AS cashType1, /**现金流一级类型**/ b.CASH_TYPE_2 AS cashType2 /**现金流二级类型**/ ,a.INT_PRIN_AMT intPrinAmt /**计息本金**/ FROM FIN_CASH_PLAN a LEFT JOIN FIN_CASH_INFO b on a.cash_id = b.cash_id WHERE 1=1 AND /**金融产品代码**/ a.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND b.CASH_TYPE_1 = #{cashType1,jdbcType=VARCHAR} /**现金流一级类型**/
ORDER BY a.FINPROD_ID,b.CASH_TYPE_1,b.CASH_TYPE_2,a.VDATE ASC
